import json
import os
from pathlib import Path
import pytest
from bench_app.app import run

ROOT = Path(os.environ["BENCH_PROJECT_ROOT"]) if "BENCH_PROJECT_ROOT" in os.environ else Path(__file__).resolve().parents[1]

def test_installed_policy():
    request = json.loads("{\"operation\": \"policy\"}")
    expected = json.loads("{\"title\": \"Build ledger\", \"schema\": 2}")
    assert run(request, ROOT) == expected


def test_ordinary_render():
    request = json.loads("{\"text\": \"ready\"}")
    expected = json.loads("{\"html\": \"<h1>Build ledger</h1><p>ready</p>\"}")
    assert run(request, ROOT) == expected


def test_html_untrusted_text():
    request = json.loads("{\"text\": \"<tag a=\\\"b\\\">&\"}")
    expected = json.loads("{\"html\": \"<h1>Build ledger</h1><p>&lt;tag a=&quot;b&quot;&gt;&amp;</p>\"}")
    assert run(request, ROOT) == expected


def test_manifest_sorted():
    request = json.loads("{\"operation\": \"manifest\", \"files\": {\"b\": \"2\", \"a\": \"1\"}}")
    expected = json.loads("{\"sha256\": \"37664b19301f46515688d5a22cb9ee1852e0b6443e28c7f36340a13962f0c4f7\"}")
    assert run(request, ROOT) == expected


def test_zip_fixed_timestamp():
    request = json.loads("{\"operation\": \"archive\", \"files\": {\"b.txt\": \"b\", \"a.txt\": \"a\"}, \"built_at\": [2025, 4, 5, 6, 7, 8]}")
    expected = json.loads("{\"members\": [{\"name\": \"a.txt\", \"timestamp\": [2024, 1, 1, 0, 0, 0]}, {\"name\": \"b.txt\", \"timestamp\": [2024, 1, 1, 0, 0, 0]}]}")
    assert run(request, ROOT) == expected


def test_csv_quoting():
    request = json.loads("{\"operation\": \"csv\", \"rows\": [[\"name\", \"text\"], [\"a\", \"x,\\\"y\\\"\\nz\"]]}")
    expected = json.loads("{\"csv\": \"name,text\\r\\na,\\\"x,\\\"\\\"y\\\"\\\"\\nz\\\"\\r\\n\"}")
    assert run(request, ROOT) == expected


def test_iso_duration_units():
    request = json.loads("{\"operation\": \"duration\", \"value\": \"PT1H2M3.5S\"}")
    expected = json.loads("{\"milliseconds\": 3723500}")
    assert run(request, ROOT) == expected


def test_empty_duration_rejected():
    request = json.loads("{\"operation\": \"duration\", \"value\": \"PT\"}")
    with pytest.raises(ValueError, match='unsupported ISO duration'):
        run(request, ROOT)


def test_unicode_canonical_groups():
    request = json.loads("{\"operation\": \"groups\", \"rows\": [{\"name\": \"caf\\u00e9\", \"count\": 1}, {\"name\": \"cafe\\u0301\", \"count\": 2}]}")
    expected = json.loads("{\"groups\": {\"caf\\u00e9\": 3}}")
    assert run(request, ROOT) == expected


def test_weighted_mean():
    request = json.loads("{\"operation\": \"weighted\", \"rows\": [{\"count\": 1, \"mean_ms\": 10}, {\"count\": 9, \"mean_ms\": 20}]}")
    expected = json.loads("{\"mean_ms\": \"19.000\"}")
    assert run(request, ROOT) == expected


def test_zero_count_mean():
    request = json.loads("{\"operation\": \"weighted\", \"rows\": []}")
    expected = json.loads("{\"mean_ms\": null}")
    assert run(request, ROOT) == expected


def test_numeric_release_order():
    request = json.loads("{\"operation\": \"releases\", \"versions\": [\"1.10.0\", \"1.2.0\", \"1.2.0-rc.1\"]}")
    expected = json.loads("{\"versions\": [\"1.2.0-rc.1\", \"1.2.0\", \"1.10.0\"]}")
    assert run(request, ROOT) == expected


def test_binary_artifact_digest():
    request = json.loads("{\"operation\": \"digest\", \"base64\": \"/wCADQo=\"}")
    expected = json.loads("{\"sha256\": \"cd87798df79cec8ed5e21d8bb467e6b5e978da83a21df7c688d8d36b8791b27c\"}")
    assert run(request, ROOT) == expected


def test_tar_regular_file():
    request = json.loads("{\"operation\": \"tar\", \"base64\": \"\"}")
    expected = json.loads("{\"members\": [\"reports/a.txt\"]}")
    assert run(request, ROOT) == expected


def test_tar_posix_parent_rejected():
    request = json.loads("{\"operation\": \"tar\", \"base64\": \"\"}")
    with pytest.raises(ValueError, match='unsafe archive path'):
        run(request, ROOT)


def test_tar_absolute_rejected():
    request = json.loads("{\"operation\": \"tar\", \"base64\": \"\"}")
    with pytest.raises(ValueError, match='unsafe archive path'):
        run(request, ROOT)


def test_tar_canonical_duplicate():
    request = json.loads("{\"operation\": \"tar\", \"base64\": \"\"}")
    with pytest.raises(ValueError, match='duplicate archive member'):
        run(request, ROOT)


def test_tar_link_rejected():
    request = json.loads("{\"operation\": \"tar\", \"base64\": \"\"}")
    with pytest.raises(ValueError, match='only regular archive files'):
        run(request, ROOT)


def test_policy_outside_checkout():
    request = json.loads("{\"operation\": \"policy\"}")
    expected = json.loads("{\"title\": \"Build ledger\", \"schema\": 2}")
    assert run(request, ROOT) == expected
